draw:
var Patm = p.patm, hHg = p.hg, L1 = p.len;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "center";
var scale = (H - 70) / (Patm > 100 ? Patm : 100) * 1.1;
var tubeW = Math.min(26, W * 0.07);
var ok = (Patm - hHg) > 1;
var L2 = ok ? L1 * (Patm + hHg) / (Patm - hHg) : 0;

function tube(cx, base, airLen, mercLen, closedDown, label) {
  var aPx = airLen * scale, mPx = mercLen * scale;
  var total = aPx + mPx + 18;
  // glass walls
  ctx.strokeStyle = C.rule;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(cx - tubeW / 2, base - total);
  ctx.lineTo(cx - tubeW / 2, base);
  ctx.lineTo(cx + tubeW / 2, base);
  ctx.lineTo(cx + tubeW / 2, base - total);
  ctx.stroke();
  // seal the closed end
  ctx.strokeStyle = C.ink;
  ctx.lineWidth = 3;
  ctx.beginPath();
  if (closedDown) { ctx.moveTo(cx - tubeW / 2, base); ctx.lineTo(cx + tubeW / 2, base); }
  else { ctx.moveTo(cx - tubeW / 2, base - total); ctx.lineTo(cx + tubeW / 2, base - total); }
  ctx.stroke();
  var airTop, mercTop;
  if (closedDown) { airTop = base - aPx; mercTop = airTop - mPx; }
  else { airTop = base - total; mercTop = airTop + aPx; }
  // air column
  ctx.fillStyle = C.paper;
  ctx.fillRect(cx - tubeW / 2 + 1, closedDown ? airTop : airTop, tubeW - 2, aPx);
  ctx.strokeStyle = C.accent;
  ctx.lineWidth = 1;
  ctx.strokeRect(cx - tubeW / 2 + 1, airTop, tubeW - 2, aPx);
  // mercury
  ctx.fillStyle = C.figure;
  ctx.fillRect(cx - tubeW / 2 + 1, mercTop, tubeW - 2, mPx);
  // labels
  ctx.fillStyle = C.ink;
  ctx.fillText(label, cx, base + 16);
  ctx.textAlign = "left";
  ctx.fillStyle = C.accent;
  ctx.fillText("air " + airLen.toFixed(1) + " cm", cx + tubeW / 2 + 6, airTop + aPx / 2 + 4);
  ctx.fillStyle = C.figure;
  ctx.fillText("Hg " + mercLen.toFixed(1) + " cm", cx + tubeW / 2 + 6, mercTop + mPx / 2 + 4);
  ctx.textAlign = "center";
}

var base = H - 26;
tube(W * 0.24, base, L1, hHg, true, "closed end down");
if (ok) {
  tube(W * 0.66, base, L2, hHg, false, "closed end up");
} else {
  ctx.fillStyle = C.ink;
  ctx.fillText("mercury would be pushed out", W * 0.68, H * 0.5);
}
// pressure annotations
ctx.fillStyle = C.faint;
ctx.textAlign = "center";
ctx.fillText("P = " + (Patm + hHg).toFixed(0) + " cmHg", W * 0.24, 16);
if (ok) ctx.fillText("P = " + (Patm - hHg).toFixed(0) + " cmHg", W * 0.66, 16);

out.note = ok
  ? "P1 = " + (Patm + hHg).toFixed(1) + " cmHg, P2 = " + (Patm - hHg).toFixed(1) + " cmHg, so L2 = L1 x P1/P2 = " + L2.toFixed(2) + " cm"
  : "Impossible: the mercury column exceeds the atmosphere, so it cannot hang there.";
